mapper.select:
MATCH (n:Instance:测点)-[:CHILD_NODE]->(attr:Instance:特征)-[:CHILD_NODE]->(bj:Instance:部件)-[:CHILD_NODE*0..]->(sb:Instance:设备) -[:CHILD_NODE*0..]->(zxt:Instance:子系统)-[:CHILD_NODE*0..]->(jz:Instance:机组)
where sb.名称 contains #{assetName}
where jz.名称 contains #{unitName}
return distinct n.源标签点名 as srcTagName, n.名称 as tagName, n.编码 as tagCode, n.源标签点描述 as tagDesc, n.类别 as tagType, n.单位 as tagUnit, attr.名称 as attrName, attr.编码 as attrCode, attr.描述 as attrDesc, attr.类别 as attrType, attr.单位 as attrUnit, bj.名称 as partName, bj.编码 as partCode, bj.描述 as partDesc, id(bj) as partId, sb.名称 as assetName, sb.编码 as assetCode, sb.描述 as assetDesc, id(sb) as assetId, zxt.名称 as subSystemName, zxt.编码 as subSystemCode, zxt.描述 as subSystemDesc, id(zxt) as subSystemId, jz.名称 as unitName, jz.编码 as unitCode, jz.描述 as unitDesc, id(jz) as unitId

MATCH (n:Instance)-[:CHILD_NODE*0..]->(m)
WHERE id(m) = #{unitId} AND n:${type}
RETURN properties(n) AS item

MATCH (n:测点:Instance)
WHERE n.名称 contains #{name}
RETURN properties(n) AS item

MATCH (n:测点:Instance)
WHERE 1=1

    AND id(n) = #{tagId}


    AND n.编码 = #{tagName}


    AND n.源标签点名 = #{srcTagName}

RETURN properties(n) AS item

MATCH p = (a)-[:CHILD_NODE]->(b:特征:Instance)-[:CHILD_NODE*0..]->(c:机组:Instance) WHERE 1=1 AND none(nod in nodes(p) where nod:故障模式) AND none(nod in nodes(p) where nod:预警模型)
AND id(a) = #{tagId}
AND a.编码 = #{tagName}
AND a.源标签点名 = #{srcTagName}
WITH p, toString(id(NODES(p)[0])) + '-' + toString(length(p)) AS pathId UNWIND RANGE(0, length(p)) AS nodeIndex WITH pathId, nodeIndex, NODES(p)[nodeIndex] AS n RETURN pathId, nodeIndex, id(n) AS nodeId, n.名称 AS nodeName

MATCH (a)-[:CHILD_NODE*0..]->(c:子系统:Instance)
WHERE 1=1

    AND id(a) = #{tagId}


    AND a.编码 = #{tagName}


    AND a.源标签点名 = #{srcTagName}

return id(c) limit 1
